class Thermometer
    private define celsius as integer;

    method constructor(aCelsius as integer)
        this.celsius <- aCelsius;
    endMethod

    public method Fahrenheit() as real
        return this.celsius * 9 / 5 + 32;
    endMethod
endClass

algorithm ConvertTemperature
    define celsius as integer;
    define thermometer as Thermometer;
    read celsius;
    thermometer <- new Thermometer(celsius);
    write thermometer.Fahrenheit();
endAlgorithm
